var pts = new List<double[]>();
foreach (var o in (object[])args["points"]) { var a = (object[])o; pts.Add(new[]{ Convert.ToDouble(a[0]), Convert.ToDouble(a[1]) }); }
var pl = doc.ActiveProjectLocation;
var tf = pl.GetTotalTransform();
var inv = tf.Inverse;
var pp = pl.GetProjectPosition(XYZ.Zero);
var conv = pts.Select((p,i) => { var s = new XYZ(p[0]/0.3048, p[1]/0.3048, 0); var it = inv.OfPoint(s); return new { pt = "P0"+(i+1), internalX_m = Math.Round(it.X*0.3048,4), internalY_m = Math.Round(it.Y*0.3048,4) }; }).ToList();
var levels = new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().OrderBy(l=>l.Elevation).Select(l=> new { l.Name, elev_m = Math.Round(l.Elevation*0.3048,3), id = l.Id.IntegerValue }).ToList();
var ftypes = new FilteredElementCollector(doc).OfClass(typeof(FloorType)).Cast<FloorType>().Where(f=>!f.IsFoundationSlab).Select(f=> new { f.Name, id = f.Id.IntegerValue }).ToList();
var av = doc.ActiveView;
return new { site = pl.Name, ew_m = Math.Round(pp.EastWest*0.3048,4), ns_m = Math.Round(pp.NorthSouth*0.3048,4), elev_m = Math.Round(pp.Elevation*0.3048,4), angle_deg = Math.Round(pp.Angle*180/Math.PI,6), activeView = av.Name, activeLevel = av.GenLevel?.Name, points = conv, levels, floorTypes = ftypes };
